}

static gboolean sid_buffer_equal_fn(gconstpointer key1, gconstpointer key2)
{
    const guint8 *sb1 = (const guint8 *)key1;
    const guint8 *sb2 = (const guint8 *)key2;

    if (sb1[0] != sb2[0])
