static gboolean DOFObjectID_HasAttributes(const DOFObjectID self)
{
    if (!self)
        return FALSE;

    /* bit 7: next attribute flag. */
    return (gboolean)(((*(const guint8 *)((const guint8 *)(self->oid) + DOFObjectID_GetClassSize(self))) & 0x80) != 0);
}

